-- Two-stage autonomy preserves subject facts and all provider call history.
ALTER TABLE armi.schema_baseline_identity DROP CONSTRAINT schema_baseline_identity_value_check;
UPDATE armi.schema_baseline_identity SET baseline_identity='armi.schema-baseline.v30';
ALTER TABLE armi.schema_baseline_identity ADD CONSTRAINT schema_baseline_identity_value_check CHECK (baseline_identity='armi.schema-baseline.v30');
ALTER TABLE armi.autonomy_plans ADD COLUMN phase text NOT NULL DEFAULT 'waiting' CHECK (phase IN ('waiting','check','execute','blocked'));
ALTER TABLE armi.autonomy_plans ADD COLUMN idle_streak integer NOT NULL DEFAULT 0 CHECK (idle_streak BETWEEN 0 AND 2);
ALTER TABLE armi.autonomy_plans ADD COLUMN failure_streak integer NOT NULL DEFAULT 0 CHECK (failure_streak BETWEEN 0 AND 3);
ALTER TABLE armi.autonomy_plans ADD COLUMN last_check_started_at timestamptz;
ALTER TABLE armi.autonomy_plans ADD COLUMN last_event_at timestamptz;
ALTER TABLE armi.autonomy_plans ADD COLUMN last_engage boolean;
ALTER TABLE armi.autonomy_plans ADD COLUMN blocked_reason_code text;
ALTER TABLE armi.autonomy_plans ADD COLUMN model_configuration_revision text;
UPDATE armi.opportunities SET current_disposition='cancelled',resolved_at=statement_timestamp(),resolution_reason_code='REC-AUTONOMY-CONTRACT-CHANGED'
WHERE source_kind='autonomy_plan' AND current_disposition IN ('open','selected');
UPDATE armi.autonomy_plans SET policy=policy-'daily_request_limit'-'minimum_consideration_seconds'-'maximum_consideration_seconds',
  plan_version=plan_version+1,opportunity_id=NULL,next_consideration_at=statement_timestamp()+interval '60 seconds';
DROP TABLE armi.autonomy_request_admissions;
ALTER TABLE armi.cognitive_attempts DROP CONSTRAINT cognitive_attempts_candidate_schema_version_check;
